// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Search logs
	// (GET /v1/logs)
	SearchLogs(ctx context.Context, request SearchLogsRequestObject) (SearchLogsResponseObject, error)
	// Log volume over time and by service and level
	// (GET /v1/logs/stats)
	LogStats(ctx context.Context, request LogStatsRequestObject) (LogStatsResponseObject, error)
	// Metrics received in the time range
	// (GET /v1/metrics/names)
	ListMetricNames(ctx context.Context, request ListMetricNamesRequestObject) (ListMetricNamesResponseObject, error)
	// Query one metric as time series
	// (GET /v1/metrics/query)
	QueryMetric(ctx context.Context, request QueryMetricRequestObject) (QueryMetricResponseObject, error)
	// Services that sent spans in the time range
	// (GET /v1/services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// Search traces
	// (GET /v1/traces)
	ListTraces(ctx context.Context, request ListTracesRequestObject) (ListTracesResponseObject, error)
	// Request volume, errors and latency of root spans over time
	// (GET /v1/traces/stats)
	TraceStats(ctx context.Context, request TraceStatsRequestObject) (TraceStatsResponseObject, error)
	// Get a full trace
	// (GET /v1/traces/{trace_id})
	GetTrace(ctx context.Context, request GetTraceRequestObject) (GetTraceResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

